<?php require __DIR__."/vendor/autoload.php"; $d = json_decode(file_get_contents("routes_data.json"), true); foreach($d as $r) { $action = $r["action"]; if($action === "Closure" || str_contains($action, "Livewire")) continue; if(str_contains($action, "@")) { list($class, $method) = explode("@", $action); if(!class_exists($class)) echo "Missing Class: $class\n"; elseif(!method_exists($class, $method)) echo "Missing Method: $action\n"; } }
